int fd;
off_t offset = 0;
off_t len = 1024 * 1024; // 1 MiB region

// Announce data will be accessed sequentially
int ret_seq = posix_fadvise(fd, offset, len, POSIX_FADV_SEQUENTIAL);

// Advise the kernel to pre-fetch the region
int ret_need = posix_fadvise(fd, offset, len, POSIX_FADV_WILLNEED);

// Advise the kernel to drop cached pages (until EOF, len=0)
int ret_dont = posix_fadvise(fd, 0, 0, POSIX_FADV_DONTNEED);

// Advise unpredictable/random access pattern
int ret_rand = posix_fadvise(fd, 0, 0, POSIX_FADV_RANDOM);

// Indicate data will only be read once
int ret_once = posix_fadvise(fd, 0, 0, POSIX_FADV_NOREUSE);
